Object.assign(window.TEM8_DICTIONARY, {"human":{"media":{"uk":"media/uk/human__gb_1.mp3","us":"media/us/human__us_1.mp3"},"oxford":{"phon":"ˈhjuːmən","pos":"adjective","senses":[{"en":"of or connected with people rather than animals, machines or gods","cn":"人的","g":"[only before noun]","ex":{"en":"the human body/brain","cn":"人体；人脑"}},{"en":"showing the weaknesses and desires that are typical of people, which means that other people should not criticize the person too much","cn":"显示人性弱点（或欲望的）的；人本性的","ex":{"en":"human weaknesses/failings","cn":"人性的弱点／缺点"}},{"en":"having the same feelings and emotions as most ordinary people","cn":"有人情味的；通人情的","ex":{"en":"He's really very human when you get to know him.","cn":"你若了解他，就知道他确实很有人情味。"}},{"en":"a person rather than an animal or a machine","cn":"人","ex":{"en":"Dogs can hear much better than humans.","cn":"狗的听觉比人灵敏得多。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"人的;人类的","en":"Human means relating to or concerning people.","ex":{"en":"...the human body.","cn":"人体"}},{"pos":"N-COUNT 可数名词","cn":"（尤指与动物或机器相对的）人","en":"You can refer to people as humans, especially when you are comparing them with animals or machines.","ex":{"en":"Its rate of growth was fast — much more like that of an ape than that of a human.","cn":"它的发育速度很快——更像猿，而不像人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（情感、弱点、错误等）人特有的显示人的本性的","en":"Human feelings, weaknesses, or errors are ones that are typical of humans rather than machines.","ex":{"en":"...an ever growing risk of human error","cn":"越来越高的人为错误的风险"}}]},"examples":[{"en":"Firefighters formed a human chain (= a line of people) to carry the children to safety.","cn":"消防队员组成人链把孩子们救到了安全的地方。"},{"en":"It's only human to want the best for your children.","cn":"为自己的孩子谋求最好的条件是人之常情。"}]},"hug":{"media":{"uk":"media/uk/hug__gb_1.mp3","us":"media/us/hug__us_1.mp3"},"oxford":{"phon":"hʌɡ","pos":"verb","senses":[{"en":"to put your arms around somebody and hold them tightly, especially to show that you like or love them","cn":"拥抱；搂抱","g":"[transitive, intransitive]","ex":{"en":"They hugged each other.","cn":"他们相互拥抱。"}},{"en":"to put your arms around something and hold it close to your body","cn":"抱紧","g":"[transitive]","ex":{"en":"She sat in the chair, hugging her knees.","cn":"她双臂抱膝坐在椅子上。"}},{"en":"to keep close to something for a distance","cn":"有一段距离地挨着（某物）","g":"[transitive]","ex":{"en":"The track hugs the coast for a mile.","cn":"那条小径离海岸只有一英里。"}},{"en":"to fit tightly around something, especially a person’s body","cn":"缠紧，缚紧（某物，尤指人体）","g":"[transitive]","ex":{"en":"figure-hugging jeans","cn":"紧身牛仔裤"}},{"en":"an act of putting your arms around somebody and holding them tightly, especially to show that you like or love them","cn":"拥抱；搂抱","ex":{"en":"She gave her mother a big hug.","cn":"她热烈地拥抱了她的母亲。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"拥抱;搂抱","en":"When you hug someone, you put your arms around them and hold them tightly, for example because you like them or are pleased to see them. You can also say that two people hug each other or that they hug .","ex":{"en":"She had hugged him exuberantly and invited him to dinner the next day","cn":"她兴高采烈地拥抱了他，并邀请他第二天一起吃晚饭。"}},{"pos":"VERB 动词","cn":"抱住，抱紧（某物）","en":"If you hug something, you hold it close to your body with your arms tightly round it.","ex":{"en":"Shaerl trudged toward them, hugging a large box","cn":"谢尔抱着一个大箱子步履艰难地向他们走去。"}},{"pos":"VERB 动词","cn":"紧挨;濒临","en":"Something that hugs the ground or a stretch of land or water stays very close to it.","ex":{"en":"The road hugs the coast for hundreds of miles","cn":"公路沿着海岸延伸数百英里。"}}]},"examples":[{"en":"He stopped to receive hugs and kisses from the fans.","cn":"他停下来接受追随者的拥抱亲吻。"},{"en":"The track hugs the coast for a mile.","cn":"那条小径有一英里紧靠海岸。"}]},"humanitarian":{"media":{"uk":"media/uk/humanitarian__gb_1.mp3","us":"media/us/humanitarian__us_1.mp3"},"oxford":{"phon":"hjuːˌmænɪˈteəriən","pos":"adjective","senses":[{"en":"connected with helping people who are suffering and improving the conditions that they are living in","cn":"人道主义的；人道主义精神的","ex":{"en":"to provide humanitarian aid to the war zone","cn":"给战区提供人道主义援助"}},{"en":"describing an event or situation that causes or involves a lot of human suffering, especially one that requires aid to be provided to a large number of people","cn":"人道主义的：描述导致或涉及很多人痛苦的事件或情况，尤其是需要向大量人提供援助的事件或情况","ex":{"en":"a humanitarian crisis","cn":"人道主义危机"}},{"en":"a person who tries to help people who are suffering and improve the conditions that they are living in","cn":"人道主义的（主张减轻人类苦难、改善人类生活）；慈善的","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"人道主义的;博爱的","en":"If a person or society has humanitarian ideas or behaviour, they try to avoid making people suffer or they help people who are suffering.","ex":{"en":"Air bombardment raised criticism on the humanitarian grounds that innocent civilians might suffer.","cn":"空袭遭到了批评，因为从人道主义的立场来看，无辜的平民可能会受到伤害。"}}]},"examples":[{"en":"The expulsion of thousands of people represents a humanitarian catastrophe of enormous proportions.","cn":"驱逐成千上万人意味着人道主义的巨大灾难。"},{"en":"They are calling for the release of the hostages on humanitarian grounds.","cn":"他们站在人道主义立场要求释放人质。"}]},"hull":{"media":{"uk":"media/uk/hull__gb_1.mp3","us":"media/us/hull__us_1.mp3"},"oxford":{"phon":"hʌl","pos":"noun","senses":[{"en":"the main, bottom part of a ship, that goes in the water","cn":"船身；船体","ex":{"en":"a wooden/steel hull","cn":"木质／钢质船体"}},{"en":"to remove the outer layer that covers peas, beans, grain, etc. or the ring of leaves attached to strawberries","cn":"剥去（豆子、谷物等）的外壳；摘掉（草莓）的花萼","ex":{"en":"First wash and hull the strawberries.","cn":"首先将草莓洗净并去皮。"},"pos":"verb"},{"en":"a port and industrial centre in Humberside in north-eastern England. It is on the River Humber.","cn":"船体：英格兰东北部亨伯赛德的港口和工业中心。它在亨伯河上。","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"船体;（坦克的）车身","en":"The hull of a boat or tank is the main body of it.","ex":{"en":"The hull had suffered extensive damage to the starboard side.","cn":"船体右舷遭到重创。"}},{"pos":"N-COUNT 可数名词","cn":"（草莓等浆果的）花萼","en":"The hull of a soft fruit such as a strawberry is the stalk and ring of leaves at the base."},{"pos":"VERB 动词","cn":"除去（草莓等浆果）的花萼","en":"If you hull soft fruit such as strawberries, you remove the hulls.","ex":{"en":"Wash and hull the strawberries.","cn":"洗一下草莓，并摘掉花萼。"}}]},"examples":[{"en":"They climbed onto the upturned hull and waited to be rescued.","cn":"他们爬上了倾覆的船体，等候救援。"},{"en":"a wooden/steel hull","cn":"木质/钢质船体"}]},"husband":{"media":{"uk":"media/uk/husband__gb_1.mp3","us":"media/us/husband__us_1.mp3"},"oxford":{"phon":"ˈhʌzbənd","pos":"noun","senses":[{"en":"the man that somebody is married to; a married man","cn":"丈夫","lab":"especially North American English","ex":{"en":"This is my husband, Steve.","cn":"这位是我的丈夫，史蒂夫。"}},{"en":"to use something very carefully and make sure that you do not waste it","cn":"节俭使用","ex":{"en":"Times are hard and we have to husband our resources.","cn":"时代很艰难，我们必须节约资源。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"丈夫","en":"A woman's husband is the man she is married to.","ex":{"en":"Eva married her husband Jack in 1957","cn":"伊娃和丈夫杰克于1957年结的婚。"}},{"pos":"VERB 动词","cn":"节约地使用;节省","en":"If you husband something valuable, you use it carefully and do not waste it.","ex":{"en":"Husbanding precious resources was part of rural life.","cn":"节约地使用宝贵的资源是乡村生活的一部分。"}}]},"examples":[{"en":"They lived together as husband and wife (= as if they were married) for years.","cn":"他们像夫妻一样共同生活了很多年。"},{"en":"This is my husband, Steve.","cn":"这位是我的丈夫，史蒂夫。"}]},"humanity":{"media":{"uk":"media/uk/humanity__gb_1.mp3","us":"media/us/humanity__us_1.mp3"},"oxford":{"phon":"hjuːˈmænəti","pos":"noun","senses":[{"en":"people in general","cn":"（统称）人；人类","g":"[uncountable]","lab":"British English","ex":{"en":"He was found guilty of crimes against humanity.","cn":"他被判犯有反人类罪。"}},{"en":"the state of being a person rather than a god, an animal or a machine","cn":"人性","g":"[uncountable]","ex":{"en":"The story was used to emphasize the humanity of Jesus.","cn":"人们用这个故事来强调耶稣人性的一面。"}},{"en":"the quality of being kind to people and animals by making sure that they do not suffer more than is necessary; the quality of being humane","cn":"人道；仁慈","g":"[uncountable]","ex":{"en":"The judge was praised for his courage and humanity.","cn":"法官的勇气和人道受到称赞。"}},{"en":"the subjects of study that are about the way people think and behave, for example literature, language, history and philosophy","cn":"人文学科","g":"[plural]","ex":{"en":"The college offers a wide range of courses in the arts and humanities.","cn":"学院开设多门艺术和人文课程。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人类;（总称）人","en":"All the people in the world can be referred to as humanity .","ex":{"en":"They face charges of committing crimes against humanity.","cn":"他们被控犯有反人类罪。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人性;人的属性","en":"A person's humanity is their state of being a human being, rather than an animal or an object.","ex":{"en":"...a man who's almost lost his humanity in his bitter hatred of his rivals.","cn":"因痛恨竞争对手而几乎丧失人性的男子"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人道;仁慈;博爱","en":"Humanity is the quality of being kind, thoughtful, and sympathetic towards others.","ex":{"en":"Her speech showed great maturity and humanity.","cn":"她的演讲思想高度成熟，并且洋溢着博爱精神。"}},{"pos":"N-PLURAL 复数名词","cn":"（历史、哲学、文学等）人文学科","en":"The humanities are the subjects such as history, philosophy, and literature which are concerned with human ideas and behaviour.","ex":{"en":"...students majoring in the humanities.","cn":"主修人文学科的学生"}}]},"examples":[{"en":"The story was used to emphasize the humanity of Jesus.","cn":"人们用这个故事来强调耶稣人性的一面。"},{"en":"united by a sense of common humanity","cn":"因一种同是人的情感而团结在一起"}]},"hugely":{"media":{"uk":"media/uk/hugely__gb_1.mp3","us":"media/us/hugely__us_1.mp3"},"oxford":{"phon":"ˈhjuːdʒli","pos":"adverb","senses":[{"en":"extremely","cn":"极其；极度","ex":{"en":"hugely entertaining/important/popular/successful","cn":"极其有趣／重要／受欢迎／成功"}},{"en":"very much","cn":"非常；深深地；大大地","ex":{"en":"They intended to invest hugely in new technology.","cn":"他们打算在新技术方面投入大量资金。"}}]},"examples":[{"en":"They intended to invest hugely in new technology.","cn":"他们打算在新技术方面投入大量资金。"},{"en":"He turned around, grinning hugely.","cn":"他转过身来，咧着嘴乐。"}]},"hunt":{"media":{"uk":"media/uk/hunt__gb_1.mp3","us":"media/us/hunt__us_1.mp3"},"oxford":{"phon":"hʌnt","pos":"verb","senses":[{"en":"to go after wild animals in order to catch or kill them for food, sport or to make money","cn":"打猎；猎取；猎杀","g":"[intransitive, transitive]","ex":{"en":"Lions sometimes hunt alone.","cn":"狮子有时单独猎食。"}},{"en":"to look for something that is difficult to find","cn":"搜寻；搜索","g":"[intransitive]","ex":{"en":"She is still hunting for a new job.","cn":"她还在找新工作。"}},{"en":"to look for somebody in order to catch them or harm them","cn":"追踪；追捕","g":"[transitive, intransitive]","ex":{"en":"Police are hunting an escaped criminal.","cn":"警察正在追捕一名逃犯。"}},{"en":"(in the UK) to go after and kill foxes as a sport, riding horses and using dogs. Fox hunting with dogs has been illegal in England and Wales since 2005, but people still ride out with dogs following a scent trail, without an actual fox.","cn":"猎（狐）（骑马用狗猎狐，英格兰和威尔士在 2005 年已立法禁止）","g":"[intransitive, transitive]","ex":{"en":"They hunt when they stay with friends in Ireland.","cn":"他们去爱尔兰时会和那儿的朋友去猎狐。"}},{"en":"an act of looking for somebody/something that is difficult to find","cn":"搜寻；搜索；寻找","g":"[countable, usually singular]","ex":{"en":"The hunt is on for a suitable candidate.","cn":"正在物色合适的人选。"},"pos":"noun"},{"en":"an act of going after wild animals to kill or capture them","cn":"打猎","g":"[countable]","ex":{"en":"a tiger/seal hunt","cn":"猎虎；猎杀海豹"},"pos":"noun"},{"en":"(in the UK) an event at which people ride horses and hunt foxes with dogs as a sport, illegal in England and Wales since 2005","cn":"猎狐（骑马用狗猎狐的运动，英格兰和威尔士在 2005 年已立法禁止）","g":"[countable]","ex":{"en":"There was always a hunt on Boxing Day.","cn":"从前节礼日总会有猎狐活动。"},"pos":"noun"},{"en":"(in the UK) a group of people who regularly hunt foxes as a sport. Since 2005, instead of a fox, they follow a specially laid scent trail.","cn":"猎狐队伍","g":"[countable + singular or plural verb]","ex":{"en":"There were several different hunts in the area.","cn":"该地区曾进行过几次不同的狩猎活动。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"搜寻;寻找","en":"If you hunt for something or someone, you try to find them by searching carefully or thoroughly.","ex":{"en":"A forensic team was hunting for clues","cn":"法医小组正在寻找线索。"}},{"pos":"VERB 动词","cn":"追踪，追捕（罪犯、敌人等）","en":"If you hunt a criminal or an enemy, you search for them in order to catch or harm them.","ex":{"en":"Detectives have been hunting him for seven months","cn":"侦探7个月来一直在追捕他。"}},{"pos":"VERB 动词","cn":"（人）打猎，猎杀;（动物）猎食","en":"When people or animals hunt, they chase and kill wild animals for food or as a sport.","ex":{"en":"As a child I learned to hunt and fish","cn":"从小我就学会了打猎和捕鱼。"}},{"pos":"VERB 动词","cn":"（在英国骑马带狗进行）猎狐","en":"In Britain, when people hunt, they ride horses over fields with dogs called hounds and try to catch and kill foxes, as a sport.","ex":{"en":"She liked to hunt as often as she could.","cn":"她喜欢一有时间就去猎狐。"}},{"pos":"N-COUNT 可数名词","cn":"（英国的）猎狐队伍","en":"In Britain, a hunt is a group of people who meet regularly to hunt foxes."},{"pos":"PHRASE 短语","cn":"（参赛队或参赛者）仍有机会赢取","en":"If a team or competitor is in the hunt for something, they still have a chance of winning it.","ex":{"en":"We're still in the hunt for the League title and we want to go all the way in the Cup.","cn":"我们仍有机会获得联赛冠军，而且我们还想一路杀进足总杯决赛。"}},{"pos":"","cn":"","en":"相关词组：hunt down hunt out"}]},"examples":[{"en":"Hundreds have joined a police hunt for the missing teenager.","cn":"已有几百人和警方一同搜寻那名失踪的少年。"},{"en":"Detectives are hunting for thieves who broke into a warehouse yesterday.","cn":"侦探正在追踪昨天侵入仓库的窃贼。"}]},"hut":{"media":{"img":["media/pic/buildings_comp.jpg","media/thumb/hut.jpg"],"uk":"media/uk/hut__gb_1.mp3","us":"media/us/hut__us_1.mp3"},"oxford":{"phon":"hʌt","pos":"noun","senses":[{"en":"a small, simply built house or shelter","cn":"简陋的小房子（或棚、舍）","ex":{"en":"You can rent a beach hut for about $10 a night.","cn":"你可以租住约10元一晚的海滩棚屋。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（简陋的）小屋;土房;棚屋;茅舍;石寮","en":"A hut is a small house with only one or two rooms, especially one which is made of wood, mud, grass, or stones."},{"pos":"N-COUNT 可数名词","cn":"（花园中的）木屋;（建筑工人等住的）临时工棚","en":"A hut is a small wooden building in someone's garden, or a temporary building used by builders or repair workers."}]},"examples":[{"en":"a beach hut","cn":"海滩棚屋"},{"en":"a wooden hut","cn":"小木屋"}]},"hundredth":{"media":{"uk":"media/uk/hundredth__gb_1.mp3","us":"media/us/hundredth__us_1.mp3"},"oxford":{"phon":"ˈhʌndrədθ","pos":"ordinal number","senses":[{"en":"100th","cn":"第一百","ex":{"en":"her hundredth birthday","cn":"她的百岁诞辰"}},{"en":"each of one hundred equal parts of something","cn":"百分之一","ex":{"en":"a/one hundredth of a second","cn":"百分之一秒"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ORD 序数词","cn":"第一百","en":"The hundredth item in a series is the one that you count as number one hundred.","ex":{"en":"The bank celebrates its hundredth anniversary in December.","cn":"这家银行将于12月庆祝其成立100周年。"}},{"pos":"FRACTION 分数词","cn":"百分之一","en":"A hundredth of something is one of a hundred equal parts of it.","ex":{"en":"Mitchell beat Lewis by three-hundredths of a second.","cn":"米切尔以0.03秒的微弱优势赢了刘易斯。"}}]},"examples":[{"en":"her hundredth birthday","cn":"她的百岁诞辰"},{"en":"a/one hundredth of a second","cn":"百分之一秒"}]},"hunched":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（常指因寒冷、生病或愁苦）耸肩弓身的，伏首前倾的","en":"If you are hunched, or hunched up, you are leaning forwards with your shoulders raised and your head down, often because you are cold, ill, or unhappy.","ex":{"en":"A solitary hunched figure emerged from Number Ten","cn":"一个缩头弓身的孤独身影从唐宁街10号出来了。"}}]},"media":{"uk":"media/uk/hunched__gb_1.mp3","us":"media/us/hunched__us_1.mp3"},"examples":[{"en":"He sat hunched over his breakfast.","cn":"他弓着背吃早饭。"},{"en":"a hunched figure","cn":"弓着背的人形"}],"oxford":{"phon":"hʌntʃt","pos":"adjective","senses":[{"en":"bending the top part of your body forward and raising your shoulders and back","cn":"弓身；弓背；耸肩","ex":{"en":"a hunched figure","cn":"弓着背的人形"}}]}},"hundred":{"media":{"uk":"media/uk/hundred__gb_1.mp3","us":"media/us/hundred__us_1.mp3"},"oxford":{"phon":"ˈhʌndrəd","pos":"number","senses":[{"en":"100","cn":"一百","ex":{"en":"One hundred (of the children) have already been placed with foster families.","cn":"有一百名（儿童）已经获安排领养。"}},{"en":"a large amount","cn":"许多；大量","lab":"usually informal","ex":{"en":"hundreds of miles away","cn":"数百里之遥"}},{"en":"the numbers from 100 to 999","cn":"100 到 999 间的数目；百位数","g":"[plural]","ex":{"en":"We're talking about a figure in the low hundreds.","cn":"我们谈论的是一个两三百的数字。"}},{"en":"the years of a particular century","cn":"某个世纪的年代","g":"[plural]","ex":{"en":"the early nineteen hundreds (= written ‘early 1900s’)","cn":"20 世纪早期"}},{"en":"used to express whole hours in the 24-hour system","cn":"（表示 24 小时制的整点）一点整、两点整、三点整等","ex":{"en":"twelve hundred hours (= 12.00 midday)","cn":"十二点整"}}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"（数字）100","en":"A hundred or one hundred is the number 100.","ex":{"en":"According to one official more than a hundred people have been arrested.","cn":"一名官员称有一百多人被捕。"}},{"pos":"QUANT 数量词","cn":"许多;大量","en":"If you refer to hundreds of things or people, you are emphasizing that there are very many of them.","ex":{"en":"Hundreds of tree species face extinction","cn":"许许多多树种濒临灭绝。"}},{"pos":"PHRASE 短语","cn":"（表示强调）百分之百，完全","en":"You can use a hundred per cent or one hundred per cent to emphasize that you agree completely with something or that it is completely right or wrong.","ex":{"en":"Are you a hundred per cent sure it's your neighbour?","cn":"你百分之百肯定是你的邻居吗？"}}]},"examples":[{"en":"Every player gave a hundred per cent tonight.","cn":"今天晚上所有的运动员都尽了最大的努力。"},{"en":"If I've said it once, I've said it a hundred times.","cn":"这事我曾经说过，而且是说过很多次了。"}]},"hurtle":{"oxford":{"phon":"ˈhɜːtl","pos":"verb","senses":[{"en":"to move very fast in a particular direction","cn":"（向某个方向）飞驰，猛冲","ex":{"en":"A runaway car came hurtling towards us.","cn":"一辆失控的汽车朝我们猛冲过来。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猛冲;飞驰","en":"If someone or something hurtles somewhere, they move there very quickly, often in a rough or violent way.","ex":{"en":"A pretty young girl came hurtling down the stairs.","cn":"一个漂亮的小女孩从楼梯上冲下来。"}}]},"media":{"uk":"media/uk/hurtle__gb_1.mp3","us":"media/us/hurtle__us_1.mp3"},"examples":[{"en":"A runaway car came hurtling towards us.","cn":"一辆失控的汽车朝我们飞驰而来。"},{"en":"All of a sudden, a car came hurtling round the corner.","cn":"突然﹐一辆汽车从拐角处冲了出来。"}]},"humility":{"oxford":{"phon":"hjuːˈmɪləti","pos":"noun","senses":[{"en":"the quality of not thinking that you are better than other people; the quality of being humble","cn":"谦逊；谦虚","ex":{"en":"Her first defeat was an early lesson in humility.","cn":"她的第一次失败使她很早便懂得了谦逊。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"谦逊;谦虚;谦恭","en":"Someone who has humility is not proud and does not believe they are better than other people.","ex":{"en":"...a deep sense of humility","cn":"极为谦虚"}}]},"media":{"uk":"media/uk/humility__gb_1.mp3","us":"media/us/humility__us_1.mp3"},"examples":[{"en":"Her first defeat was an early lesson in humility.","cn":"她的第一次失败使她很早便懂得了谦逊。"},{"en":"an act of genuine humility","cn":"真正谦虚的举动"}]},"humble":{"media":{"uk":"media/uk/humble__gb_1.mp3","us":"media/us/humble__us_1.mp3"},"oxford":{"phon":"ˈhʌmbl","pos":"adjective","senses":[{"en":"showing you do not think that you are as important as other people","cn":"谦逊的；虚心的","ex":{"en":"Be humble enough to learn from your mistakes.","cn":"要虚心地从自己的错误中学习。"}},{"en":"used to suggest that you are not as important as other people, but in a way that is not sincere or not very serious","cn":"（表示谦逊，但不够诚挚或认真）","lab":"ironic or humorous","ex":{"en":"In my humble opinion, you were in the wrong.","cn":"依拙见，你错了。"}},{"en":"having a low rank or social position","cn":"（级别或地位）低下的，卑微的","ex":{"en":"a man of humble birth/origins","cn":"出身低微的人"}},{"en":"not large or special in any way","cn":"不大的；没有特别之处的","ex":{"en":"a humble farmhouse","cn":"小农舍"}},{"en":"to make somebody feel that they are not as good or important as they thought they were","cn":"贬低；使感到卑微","ex":{"en":"He was humbled by her generosity.","cn":"她的大度使他觉得自己渺小。"},"pos":"verb"},{"en":"to easily defeat an opponent, especially a strong or powerful one","cn":"轻松打败（尤指强大的对手）","g":"[usually passive]","ex":{"en":"The world champion was humbled last night in three rounds.","cn":"这位世界冠军昨晚三个回合就被轻松击败。"},"pos":"verb"},{"en":"to show that you are not too proud to ask for something, admit that you have been wrong, etc.","cn":"低声下气；谦逊；虚心","ex":{"en":"He refused to humble himself and ask her forgiveness.","cn":"他拒绝谦卑自己并请求她的原谅。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"谦逊的;谦虚的;谦卑的","en":"A humble person is not proud and does not believe that they are better than other people.","ex":{"en":"He gave a great performance, but he was very humble","cn":"他的表演非常出色，但他却很谦虚。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（社会地位）低下的，卑贱的","en":"People with low social status are sometimes described as humble.","ex":{"en":"Spyros Latsis started his career as a humble fisherman in the Aegean","cn":"斯皮罗斯·拉齐斯的第一份职业是爱琴海上一名地位卑贱的渔夫。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"粗陋的;简陋的;不起眼的","en":"A humble place or thing is ordinary and not special in any way.","ex":{"en":"There are restaurants, both humble and expensive, that specialize in them","cn":"专门做这些菜的餐馆既有毫不起眼的也有价格昂贵的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愚（见）；拙（见）","en":"People use humble in a phrase such as in my humble opinion as a polite way of emphasizing what they think, even though they do not feel humble about it.","ex":{"en":"It is, in my humble opinion, perhaps the best steak restaurant in Great Britain.","cn":"依拙见，这可能是英国最好的牛排馆。"}},{"pos":"PHRASE 短语","cn":"道歉赔不是;承认错误","en":"If you eat humble pie, you speak or behave in a way which tells people that you admit you were wrong about something.","ex":{"en":"Anson was forced to eat humble pie and publicly apologise to her.","cn":"安森被迫认错并公开向她道歉。"}},{"pos":"VERB 动词","cn":"轻易击败（强大的对手）","en":"If you humble someone who is more important or powerful than you, you defeat them easily.","ex":{"en":"Honda won fame in the 1980s as the little car company that humbled the industry giants","cn":"本田在20世纪80年代作为一家轻易挫败行业巨头的小汽车公司而声名鹊起。"}},{"pos":"VERB 动词","cn":"使谦逊;使感到卑微;羞辱","en":"If something or someone humbles you, they make you realize that you are not as important or good as you thought you were.","ex":{"en":"Ted's words humbled me","cn":"特德的话让我感到自惭。"}}]},"examples":[{"en":"The company has worked its way up from humble beginnings to become the market leader.","cn":"公司已从创业期的微不足道发展成了市场的主导者。"},{"en":"The world champion was humbled last night in three rounds.","cn":"这位世界冠军昨晚三个回合就被轻松击败。"}]},"huge":{"media":{"uk":"media/uk/huge__gb_1.mp3","us":"media/us/huge__us_1.mp3","img":["media/ldoce/img/huge.jpg"]},"oxford":{"phon":"hjuːdʒ","pos":"adjective","senses":[{"en":"extremely large in size or amount; great in degree","cn":"巨大的；极多的；程度高的","ex":{"en":"The sums of money involved are potentially huge.","cn":"涉及的金额可能很大。"}},{"en":"very successful","cn":"非常成功的；走红的","lab":"informal","ex":{"en":"I think this band is going to be huge.","cn":"我想这支乐队要走红了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（体积）巨大的，庞大的","en":"Something or someone that is huge is extremely large in size.","ex":{"en":"...a tiny little woman with huge black glasses","cn":"戴着一副硕大黑框眼镜的娇小女子"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（数量、程度上）巨大的，极大的","en":"Something that is huge is extremely large in amount or degree.","ex":{"en":"I have a huge number of ties because I never throw them away","cn":"我有超多条领带，因为我从来不肯扔掉它们。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（规模上）巨大的，极大的","en":"Something that is huge exists or happens on a very large scale, and involves a lot of different people or things.","ex":{"en":"Another team is looking at the huge problem of debts between companies","cn":"另一组人正在研究公司间严重的债务问题。"}}]},"examples":[{"en":"He gazed up at her with huge brown eyes.","cn":"他睁着棕色的大眼睛盯着她。"},{"en":"This is going to be a huge problem for us.","cn":"这将是我们的一大难题。"}]},"hubris":{"media":{"uk":"media/uk/hubris__gb_1.mp3","us":"media/us/hubris__us_1.mp3"},"oxford":{"phon":"ˈhjuːbrɪs","pos":"noun","senses":[{"en":"the fact of being too proud. In literature, a character with this quality ignores warnings and laws and this usually results in their downfall and death.","cn":"傲慢；狂妄","ex":{"en":"He thought he was above the law and was ultimately punished for his hubris.","cn":"他认为自己能凌驾于法律之上，最终因狂妄自大受到了惩罚。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"傲慢;自大;自恃","en":"If you accuse someone of hubris, you are accusing them of arrogant pride.","ex":{"en":"...a tale of how an honourable man pursuing honourable goals was afflicted with hubris and led his nation towards catastrophe.","cn":"关于一个追求崇高目标的磊落君子是如何因自高自大而将自己的国家引向灾难的故事"}}]}},"humiliating":{"media":{"uk":"media/uk/humiliating__gb_1.mp3","us":"media/us/humiliating__us_1.mp3"},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"使人蒙受耻辱的;让人出丑的;丢脸的","en":"If something is humiliating, it embarrasses you and makes you feel ashamed and stupid.","ex":{"en":"The Conservatives have suffered a humiliating defeat","cn":"保守党人遭受到了一次颜面尽失的失败。"}}]},"examples":[{"en":"a humiliating defeat","cn":"耻辱的失败"}],"oxford":{"phon":"hjuːˈmɪlieɪtɪŋ","pos":"adjective","senses":[{"en":"making somebody feel ashamed or stupid and lose the respect of other people","cn":"让某人感到羞耻或愚蠢并失去他人的尊重","ex":{"en":"a humiliating defeat","cn":"耻辱的失败"}}]}},"hunts":{"oxford":{"phon":"hʌnt","pos":"verb","senses":[{"en":"to chase wild animals or birds in order to catch or kill them for food, sport or to make money","cn":"打猎；猎取；猎杀"},{"en":"to look for sth that is difficult to find","cn":"搜寻；搜索"}]},"media":{"uk":"media/uk/hunt__gb_1.mp3","us":"media/us/hunt__us_1.mp3"}},"hurried":{"media":{"uk":"media/uk/hurried__gb_1.mp3","us":"media/us/hurried__us_1.mp3"},"oxford":{"phon":"ˈhʌrid","pos":"adjective","senses":[{"en":"done too quickly because you do not have enough time","cn":"匆忙完成的；仓促而就的","ex":{"en":"I ate a hurried breakfast and left.","cn":"我匆匆忙忙吃完早饭就离开了。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行动）匆忙的，迅速的","en":"A hurried action is done quickly, because you do not have much time to do it in.","ex":{"en":"...a hurried breakfast.","cn":"匆忙塞了几口的早餐"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（行动）仓促的，突然的，急于应对的","en":"A hurried action is done suddenly, in reaction to something that has just happened.","ex":{"en":"Downing Street denied there had been a hurried overnight redrafting of the text.","cn":"唐宁街否认连夜赶工改拟了文本。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（人）做事匆忙的，行动仓促的","en":"Someone who is hurried does things more quickly than they should because they do not have much time to do them.","ex":{"en":"Parisians on the street often looked worried, hurried and unfriendly.","cn":"巴黎街上的路人往往看上去忧心忡忡、匆匆忙忙而且不太友善。"}}]},"examples":[{"en":"I ate a hurried breakfast and left.","cn":"我匆匆忙忙吃完早饭就离开了。"},{"en":"I hurriedly got up and dressed.","cn":"我急忙起床穿好衣服。"}]},"hurts":{"oxford":{"phon":"hɜːt","pos":"verb","senses":[{"en":"to cause physical pain to sb/yourself; to injure sb/yourself （","cn":"使）疼痛，受伤"},{"en":"to feel painful","cn":"感到疼痛"}]}},"hunted":{"oxford":{"phon":"ˈhʌntɪd","pos":"adjective","senses":[{"en":"showing that somebody is very worried or frightened, as if somebody is following them and trying to catch them","cn":"（像被人追踪般）惴惴不安的，惊恐万分的","ex":{"en":"His eyes had a hunted look.","cn":"他的双眼透露出恐慌的神色。"}}]},"media":{"uk":"media/uk/hunted__gb_1.mp3","us":"media/us/hunted__us_1.mp3"},"examples":[{"en":"His eyes had a hunted look.","cn":"他双眼透露出恐慌的神态。"}]},"hunger":{"media":{"uk":"media/uk/hunger__gb_1.mp3","us":"media/us/hunger__us_1.mp3"},"oxford":{"phon":"ˈhʌŋɡə(r)","pos":"noun","senses":[{"en":"the state of not having enough food to eat, especially when this causes illness or death","cn":"饥饿；饥荒","g":"[uncountable]","ex":{"en":"Around fifty people die of hunger every day in the camp.","cn":"集中营里每天大约有五十人饿死。"}},{"en":"the feeling caused by a need to eat","cn":"饥饿感；食欲；胃口","g":"[uncountable]","ex":{"en":"If you feel hunger pangs between meals, eat some fruit or nuts.","cn":"如果您在两餐之间感到饥饿，可以吃一些水果或坚果。"}},{"en":"a strong desire for something","cn":"渴望；渴求","g":"[singular]","lab":"formal","ex":{"en":"She has an insatiable hunger for knowledge.","cn":"她对知识有着无止境的渴求。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"饥饿感","en":"Hunger is the feeling of weakness or discomfort that you get when you need something to eat.","ex":{"en":"Hunger is the body's signal that levels of blood sugar are too low","cn":"饥饿感是身体发出的信号，表示血糖水平太低。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"饥饿;饥荒","en":"Hunger is a severe lack of food which causes suffering or death.","ex":{"en":"Three hundred people in this town are dying of hunger every day.","cn":"该镇每天有300人濒于饿死。"}},{"pos":"N-SING 单数名词","cn":"渴望;渴求","en":"If you have a hunger for something, you want or need it very much.","ex":{"en":"Geffen has a hunger for success that seems bottomless.","cn":"格芬的成功欲望似乎永无止境。"}},{"pos":"VERB 动词","cn":"渴望;渴求","en":"If you say that someone hungers for something or hungers after it, you are emphasizing that they want it very much.","ex":{"en":"But Jules was not eager for classroom learning, he hungered for adventure.","cn":"但朱尔斯对坐在课堂里学习并不热心，他渴望冒险。"}}]},"examples":[{"en":"The organization works to alleviate world hunger and disease.","cn":"这个机构致力于减少世界上的饥饿和疾病。"},{"en":"Nothing seemed to satisfy their hunger for truth.","cn":"似乎没有什么能满足他们对真理的渴求。"}]},"humour":{"oxford":{"phon":"ˈhjuːmə(r)","pos":"noun","senses":[{"en":"the quality in something that makes it funny; the ability to laugh at things that are funny","cn":"幽默；幽默感","g":"[uncountable]","ex":{"en":"It was a story full of gentle humour.","cn":"这是一个充满温柔幽默的故事。"}},{"en":"the state of your feelings or mind at a particular time","cn":"感觉；心情；精神状态","g":"[countable, uncountable]","lab":"formal","ex":{"en":"to be in the best of humours","cn":"情绪极好"}},{"en":"one of the four liquids that were thought in the past to be in a person’s body and to influence health and character","cn":"体液（旧时认为存在人体内，有四种，可影响健康和性格）","g":"[countable]","lab":"old use"},{"en":"to agree with somebody’s wishes, even if they seem unreasonable, in order to keep the person happy","cn":"迁就；顺应","ex":{"en":"She thought it best to humour him rather than get into an argument.","cn":"她想最好是顺他的意，而不是和他争吵。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"幽默的谈吐;笑话","en":"You can refer to the amusing things that people say as their humour .","ex":{"en":"Her humour and determination were a source of inspiration to others.","cn":"她的幽默言谈和坚定决心对其他人来说是一种鼓舞。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"幽默;诙谐;滑稽","en":"Humour is a quality in something that makes you laugh, for example in a situation, in someone's words or actions, or in a book or film.","ex":{"en":"She felt sorry for the man but couldn't ignore the humour of the situation.","cn":"她很同情这个男人，但这一情景又让她忍俊不禁。"}},{"pos":"N-VAR 可变名词","cn":"心情;情绪","en":"If you are in a good humour, you feel cheerful and happy, and are pleasant to people. If you are in a bad humour, you feel bad-tempered and unhappy, and are unpleasant to people.","ex":{"en":"Christina was still not clear why he had been in such ill humour","cn":"克里斯蒂娜仍搞不清楚为什么他情绪这么差。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"精神状态","en":"If you do something with good humour, you do it cheerfully and pleasantly.","ex":{"en":"Hugo bore his illness with great courage and good humour.","cn":"雨果以巨大的勇气和良好的精神状态面对疾病。"}},{"pos":"VERB 动词","cn":"迁就;迎合","en":"If you humour someone who is behaving strangely, you try to please them or pretend to agree with them, so that they will not become upset.","ex":{"en":"She disliked Dido but was prepared to tolerate her for a weekend in order to humour her husband.","cn":"她不喜欢迪多，但准备暂时忍受她一个周末，以迁就自己的丈夫。"}}]},"media":{"uk":"media/uk/humour__gb_1.mp3","us":"media/us/humour__us_1.mp3"},"examples":[{"en":"The film is only funny if you appreciate French humour (= things that cause French people to laugh).","cn":"只有能理解法国式的幽默才会领略这部电影的趣味。"},{"en":"She thought it best to humour him rather than get into an argument.","cn":"她想最好是顺他的意，而不和他争吵。"}]},"hustle":{"oxford":{"phon":"ˈhʌsl","pos":"verb","senses":[{"en":"to make somebody move quickly by pushing them in a rough aggressive way","cn":"推搡；猛推","g":"[transitive]","ex":{"en":"He grabbed her arm and hustled her out of the room.","cn":"他抓住她的胳膊把她推出房间。"}},{"en":"to force somebody to make a decision before they are ready or sure","cn":"催促（某人做决定）","g":"[transitive]","ex":{"en":"All the family felt that Stephen had been hustled into the engagement by Claire.","cn":"全家人都觉得斯蒂芬是被克莱尔催促订婚的。"}},{"en":"to sell or obtain something, often illegally","cn":"（常指非法地）兜售，取得","g":"[transitive, intransitive]","lab":"informal, especially North American English，，","ex":{"en":"to hustle dope","cn":"兜售麻醉品"}},{"en":"to act in an aggressive way or with a lot of energy","cn":"强行；强迫；硬干","g":"[intransitive]","lab":"North American English, informal，，"},{"en":"to work as a prostitute","cn":"当妓女","g":"[intransitive]","lab":"North American English"},{"en":"busy noisy activity of a lot of people in one place","cn":"忙碌喧嚣","g":"[uncountable]","ex":{"en":"We escaped from the hustle and bustle of the city for the weekend.","cn":"我们周末时躲开了城市的拥挤喧嚣。"},"pos":"noun"},{"en":"a situation in which somebody uses dishonest or illegal methods in order to achieve something, usually to get money","cn":"欺诈行为；欺骗手段","g":"[countable]","lab":"North American English, informal，，","ex":{"en":"Many ex-convicts find it hard to get regular work and return to their old hustles in order to survive.","cn":"许多刑满释放人员发现很难找到正常的工作，为了生存又回到原来的生活。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"猛推;猛拉;推搡","en":"If you hustle someone, you try to make them go somewhere or do something quickly, for example by pulling or pushing them along.","ex":{"en":"The guards hustled Harry out of the car","cn":"卫兵将哈里从车里拉了出来。"}},{"pos":"VERB 动词","cn":"快速行走;赶紧","en":"If you hustle, you go somewhere or do something as quickly as you can.","ex":{"en":"You'll have to hustle if you're to get home for supper","cn":"你想赶回家吃晚饭的话，就得加快速度。"}},{"pos":"VERB 动词","cn":"（常指用不正当或非法的手段）谋取;骗钱;诈取","en":"If someone hustles, they try to earn money or gain an advantage from a situation, often by using dishonest or illegal means.","ex":{"en":"We're expected to hustle and fight for what we want","cn":"我们应该为得到自己想要的而不择手段，奋力争取。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"熙攘;忙碌","en":"Hustle is busy, noisy activity.","ex":{"en":"Shell Cottage provides the perfect retreat from the hustle and bustle of London","cn":"谢尔农舍为想要躲避伦敦的忙碌喧嚣的人们提供了一个绝佳的休闲之所。"}}]},"media":{"uk":"media/uk/hustle__gb_1.mp3","us":"media/us/hustle__us_1.mp3"},"examples":[{"en":"We escaped from the hustle and bustle of the city for the weekend.","cn":"我们周末时躲开了城市的拥挤喧嚣。"},{"en":"He grabbed her arm and hustled her out of the room.","cn":"他抓住她的胳膊把她推出房间。"}]},"hush":{"media":{"uk":"media/uk/hush__gb_1.mp3","us":"media/us/hush__us_1.mp3"},"oxford":{"phon":"hʌʃ","pos":"verb","senses":[{"en":"to be quiet; to stop talking or crying","cn":"安静；别说话；别叫喊","g":"[intransitive]","ex":{"en":"Hush now and try to sleep.","cn":"别出声了，睡吧。"}},{"en":"to make somebody/something become quieter; to make somebody stop talking, crying, etc.","cn":"使安静下来；使停止说话（或叫喊等）","g":"[transitive]","ex":{"en":"She tenderly hushed the baby in her arms.","cn":"她温柔地把怀里的孩子安静下来。"}},{"en":"a period of silence, especially following a lot of noise, or when people are expecting something to happen","cn":"寂静；鸦雀无声","lab":"British English, informal，，","ex":{"en":"There was a deathly hush in the theatre.","cn":"戏院里一片寂静。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"CONVENTION 惯用语","cn":"（用于要求或命令别人安静）嘘","en":"You say 'Hush!' to someone when you are asking or telling them to be quiet.","ex":{"en":"Hush, my love, it's all right.","cn":"嘘，宝贝，没事了。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）安静下来;（使）停止说话","en":"If you hush someone or if they hush, they stop speaking or making a noise.","ex":{"en":"She tried to hush her noisy father","cn":"她试图让吵吵嚷嚷的父亲安静下来。"}},{"pos":"N-SING 单数名词","cn":"寂静;宁静;（突然出现的）安静","en":"You say there is a hush in a place when everything is quiet and peaceful, or suddenly becomes quiet.","ex":{"en":"A hush fell over the crowd and I knew something terrible had happened.","cn":"人群突然一片肃静，我知道一定发生了什么可怕的事。"}},{"pos":"","cn":"","en":"相关词组：hush up"}]},"examples":[{"en":"He claimed that the whole affair had been hushed up by the council.","cn":"他声称整个事件都被议会一手捂住了。"},{"en":"A hush descended over the waiting crowd.","cn":"等候着的人群变得鸦雀无声。"}]},"hurry":{"media":{"uk":"media/uk/hurry__gb_1.mp3","us":"media/us/hurry__us_1.mp3"},"oxford":{"phon":"ˈhʌri","pos":"verb","senses":[{"en":"to move or act quickly because there is not much time","cn":"赶快，匆忙，急忙（做某事）","g":"[intransitive]","ex":{"en":"You'll have to hurry if you want to catch that train.","cn":"如果你想赶上那趟火车就得抓紧时间了。"}},{"en":"to move quickly in a particular direction","cn":"（朝某方向）迅速移动","g":"[intransitive]","ex":{"en":"He picked up his bags and hurried across the courtyard.","cn":"他拎起提包匆匆穿过院子。"}},{"en":"to make somebody do something more quickly","cn":"催促（某人）","g":"[transitive]","ex":{"en":"I don't want to hurry you but we close in twenty minutes.","cn":"我并不想催你，但我们再过二十分钟就要关门。"}},{"en":"to deal with something quickly","cn":"迅速处理","g":"[transitive]","ex":{"en":"Her application was hurried through.","cn":"她的申请很快得到了处理。"}},{"en":"to do something too quickly","cn":"仓促（做某事）","g":"[transitive, usually passive]","ex":{"en":"A good meal should never be hurried.","cn":"美餐绝不能狼吞虎咽。"}},{"en":"the need or wish to get something done quickly","cn":"匆忙；急忙","ex":{"en":"Take your time—there's no hurry.","cn":"悠着点，不用急。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"匆忙地走","en":"If you hurry somewhere, you go there as quickly as you can.","ex":{"en":"Claire hurried along the road","cn":"克莱尔匆匆地沿路而行。"}},{"pos":"VERB 动词","cn":"赶紧（做）;急忙（做）；匆忙（做）","en":"If you hurry to do something, you start doing it as soon as you can, or try to do it quickly.","ex":{"en":"Mrs Hardie hurried to make up for her tactlessness by asking her guest about his holiday","cn":"哈迪夫人赶紧问客人假期过得怎么样，替自己的言不得体打圆场。"}},{"pos":"N-SING 单数名词","cn":"急忙;匆忙;仓促","en":"If you are in a hurry to do something, you need or want to do something quickly. If you do something in a hurry, you do it quickly or suddenly.","ex":{"en":"Kate was in a hurry to grow up, eager for knowledge and experience","cn":"凯特急于长大，渴望获取知识和经验。"}},{"pos":"VERB 动词","cn":"同 hurry up","en":"To hurry something means the same as to hurry up something.","ex":{"en":"...The President's attempt to hurry the process of independence.","cn":"总统试图加快独立进程的努力"}},{"pos":"VERB 动词","cn":"催促;使赶紧","en":"If you hurry someone to a place or into a situation, you try to make them go to that place or get into that situation quickly.","ex":{"en":"Rachel hurried him to his bed","cn":"雷切尔催着他上了床。"}},{"pos":"PHRASE 短语","cn":"不必着急;不忙","en":"If you say to someone 'There's no hurry' or 'I'm in no hurry' you are telling them that there is no need for them to do something immediately.","ex":{"en":"I'll need to talk with you, but there's no hurry","cn":"我得和你谈谈，但不着急。"}},{"pos":"PHRASE 短语","cn":"不愿（做）;不想（做）","en":"If you are in no hurry to do something, you are very unwilling to do it.","ex":{"en":"I love it at St Mirren so I'm in no hurry to go anywhere","cn":"我喜欢在圣米伦的生活，所以我哪里也不愿去。"}},{"pos":"","cn":"","en":"相关词组：hurry along hurry up"}]},"examples":[{"en":"I don't want to hurry you but we close in twenty minutes.","cn":"我并不想催你，但我们再过二十分钟就要关门。"},{"en":"Sorry, I haven't got time to do it now — I'm in a hurry.","cn":"对不起，我现在没时间管这个，我忙着呢。"}]},"hub":{"media":{"uk":"media/uk/hub__gb_1.mp3","us":"media/us/hub__us_1.mp3"},"oxford":{"phon":"hʌb","pos":"noun","senses":[{"en":"a central airport, station, etc. that operates many services","cn":"中心，枢纽（如机场、车站等）","ex":{"en":"The airport has become an international hub.","cn":"这个机场已成为国际枢纽。"}},{"en":"the central and most important part of a particular place or activity","cn":"（某地或活动的）中心，核心","g":"[usually singular]","ex":{"en":"the commercial hub of the city","cn":"城市的商业中心"}},{"en":"the central part of a wheel","cn":"轮毂"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（活动的）中心，核心","en":"You can describe a place as a hub of an activity when it is a very important centre for that activity.","ex":{"en":"The island's social hub is the Cafe Sport","cn":"该岛的社交中心是“体育咖啡馆”。"}},{"pos":"N-COUNT 可数名词","cn":"（轮）毂","en":"The hub of a wheel is the part at the centre."},{"pos":"N-COUNT 可数名词","cn":"航空枢纽;中心机场","en":"A hub or a hub airport is a large airport from which you can travel to many other airports.","ex":{"en":"...a campaign to secure Heathrow's place as Europe's main international hub.","cn":"旨在稳固希思罗机场作为欧洲主要航空枢纽地位的宣传活动"}},{"pos":"","cn":"（网络）集线器","en":"A hub is a device for connecting computers in a network."}]},"examples":[{"en":"the commercial hub of the city","cn":"城市的商业中心"},{"en":"to be at the hub of things (= where things happen and important decisions are made)","cn":"在核心部门"}]},"humorous":{"media":{"uk":"media/uk/humorous__gb_1.mp3","us":"media/us/humorous__us_1.mp3"},"oxford":{"phon":"ˈhjuːmərəs","pos":"adjective","senses":[{"en":"funny; showing a sense of humour","cn":"滑稽有趣的；有幽默感的","ex":{"en":"He gave a humorous account of their trip to Spain.","cn":"他饶有风趣地讲述了他们的西班牙之行。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"滑稽的;（尤指）幽默的,诙谐的","en":"If someone or something is humorous, they are amusing, especially in a clever or witty way.","ex":{"en":"He was quite humorous, and I liked that about him.","cn":"他很幽默，我喜欢他这一点。"}}]},"examples":[{"en":"He gave a humorous account of their trip to Spain.","cn":"他饶有风趣地讲述了他们的西班牙之行。"},{"en":"The poem humorously describes local characters and traditions.","cn":"那首诗幽默地描述了当地的人物和传统。"}]},"huddle":{"media":{"uk":"media/uk/huddle__gb_1.mp3","us":"media/us/huddle__us_1.mp3"},"oxford":{"phon":"ˈhʌdl","pos":"verb","senses":[{"en":"to gather closely together, usually because of cold or fear","cn":"（通常因寒冷或害怕）挤在一起","g":"[intransitive]","ex":{"en":"We huddled together for warmth.","cn":"我们挤在一块取暖。"}},{"en":"to hold your arms and legs close to your body, usually because you are cold or frightened","cn":"（通常因寒冷或害怕）蜷缩，缩成一团","g":"[intransitive]","ex":{"en":"I huddled under a blanket on the floor.","cn":"我在地板上盖着毯子缩成一团。"}},{"en":"a small group of people, objects or buildings that are close together, especially when they are not in any particular order","cn":"（尤指杂乱地）挤在一起的人（或物品、建筑）","ex":{"en":"People stood around in huddles.","cn":"人们三五成群地到处聚集着。"},"pos":"noun"},{"en":"a time when the players gather round to hear the plan for the next part of the game","cn":"队员靠拢（磋商战术）","ex":{"en":"The team went into a huddle at half-time to discuss their tactics.","cn":"中场休息时队员围成一圈讨论战术。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常因寒冷或恐惧而）蜷缩，缩成一团","en":"If you huddle somewhere, you sit, stand, or lie there holding your arms and legs close to your body, usually because you are cold or frightened.","ex":{"en":"She huddled inside the porch as she rang the bell","cn":"她按门铃时身子在门廊里缩成一团。"}},{"pos":"VERB 动词","cn":"（通常因寒冷或恐惧而）聚在一起，挤成一团","en":"If people huddle together or huddle round something, they stand, sit, or lie close to each other, usually because they all feel cold or frightened.","ex":{"en":"Tired and lost, we huddled together","cn":"我们疲惫不堪，又迷了路，于是大家都挤在一起。"}},{"pos":"V-RECIP 相互动词","cn":"（私下）开会;(暗中)碰头","en":"If people huddle in a group, they gather together to discuss something quietly or secretly.","ex":{"en":"Off to one side, Sticht, Macomber, Jordan, and Kreps huddled to discuss something","cn":"施蒂希特、麦康伯、乔丹和克雷普斯走到一旁私下商量着什么。"}},{"pos":"N-COUNT 可数名词","cn":"拥挤的一群;杂乱的一堆","en":"A huddle is a small group of people or things that are standing very close together or lying on top of each other, usually in a disorganized way.","ex":{"en":"We lay there: a huddle of bodies, gasping for air","cn":"我们横七竖八地挤作一团躺在那里，大口喘着气。"}}]},"examples":[{"en":"The track led them to a huddle of outbuildings.","cn":"那条小路把他们带到了一片杂乱拥挤的棚子。"},{"en":"I huddled under a blanket on the floor.","cn":"我在地板上盖着毯子缩成一团。"}]},"hung":{"media":{"uk":"media/uk/hung__gb_2.mp3","us":"media/us/hung__us_2.mp3"},"oxford":{"phon":"hʌŋ","pos":"adjective","senses":[{"en":"in which no political party has more elected members than all the other parties added together","cn":"任何政党都不占多数席位的","lab":"British English","ex":{"en":"a hung parliament","cn":"悬浮议会"}},{"en":"unable to agree about whether somebody is guilty of a crime","cn":"不能取得一致意见的"}]},"collins":{"senses":[{"pos":"","cn":"","en":"Hung is the past tense and past participle of most of the senses of hang ."},{"pos":"ADJ 形容词","cn":"（陪审团）不能达成一致意见的;（英国议会或政务委员会）任何政党都不占多数席位的","en":"A hung jury is the situation that occurs when a jury is unable to reach a decision because there is not a clear majority of its members in favour of any one decision. In British English you can also talk about a hung parliament or a hung council.","ex":{"en":"In the event of a hung Parliament he would still fight for everything in the manifesto","cn":"假如出现一个没有多数党的议会，他也仍将继续为实现宣言里提出的所有目标而奋斗。"}}]}},"humor":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/humor__gb_1.mp3","us":"media/us/humor__us_1.mp3"},"oxford":{"phon":"ˈhjuːmə(r)","pos":"noun","senses":[{"en":"the quality in something that makes it funny; the ability to laugh at things that are funny","cn":"幽默；幽默感","g":"[uncountable]","ex":{"en":"It was a story full of gentle humor.","cn":"这是一个充满温柔幽默的故事。"}},{"en":"the state of your feelings or mind at a particular time","cn":"感觉；心情；精神状态","g":"[countable, uncountable]","lab":"formal","ex":{"en":"to be in the best of humors","cn":"保持最佳心情"}},{"en":"one of the four liquids that were thought in the past to be in a person’s body and to influence health and character","cn":"体液（旧时认为存在人体内，有四种，可影响健康和性格）","g":"[countable]","lab":"old use"},{"en":"to agree with somebody’s wishes, even if they seem unreasonable, in order to keep the person happy","cn":"迁就；顺应","ex":{"en":"She thought it best to humor him rather than get into an argument.","cn":"她认为最好是迁就他，而不是陷入争论。"},"pos":"verb"}]}},"humankind":{"oxford":{"phon":"ˌhjuːmənˈkaɪnd","pos":"noun","senses":[{"en":"people in general","cn":"（统称）人；人类","ex":{"en":"These advances should be used for the benefit of all humankind.","cn":"这些进步应该用于造福全人类。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 mankind","en":"Humankind is the same as mankind ."}]},"media":{"uk":"media/uk/humankind__gb_1.mp3","us":"media/us/humankind__us_1.mp3"}},"hurting":{"oxford":{"phon":"hɜːt","pos":"verb","senses":[{"en":"to cause physical pain to sb/yourself; to injure sb/yourself （","cn":"使）疼痛，受伤"},{"en":"to feel painful","cn":"感到疼痛"}]}},"hunting":{"media":{"uk":"media/uk/hunting__gb_1.mp3","us":"media/us/hunting__us_1.mp3"},"oxford":{"phon":"ˈhʌntɪŋ","pos":"noun","senses":[{"en":"going after and killing wild animals as a sport or for food","cn":"狩猎运动；打猎","ex":{"en":"He goes hunting every weekend.","cn":"他每个周末都去打猎。"}},{"en":"a sport in which foxes are hunted by specially trained dogs and by people on horses. Fox hunting with dogs is now illegal in the UK.","cn":"猎狐（一种体育运动，如今在英国用狗猎狐是违法的）","g":"[uncountable]","lab":"British English"},{"en":"the process of looking for something","cn":"找；寻找","ex":{"en":"How's the job-hunting going?","cn":"工作找得怎么样了？"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"打猎;狩猎;（野兽的）猎食","en":"Hunting is the chasing and killing of wild animals by people or other animals, for food or as a sport.","ex":{"en":"Hunting is one of Italy's most popular sports","cn":"狩猎是意大利最受欢迎的体育运动之一。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"搜寻;寻找","en":"Hunting is the activity of searching for a particular thing.","ex":{"en":"Jobclub can help you with job hunting.","cn":"失业救助所可以为您在求职方面提供帮助。"}}]},"examples":[{"en":"Since 1977 otter hunting has been illegal.","cn":"捕猎水獭 1977 年以后就被列为非法了。"},{"en":"We're going house-hunting at the weekend.","cn":"周末我们去找房子。"}]},"humbly":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"not wanting to talk about your abilities or achievements and to say that you are good at something, even when you are – used to show approval","cn":""},{"en":"not wanting to talk about yourself or to attract attention","cn":""}]},"examples":[{"en":"He started his career as a humble peanut farmer.","cn":"","src":"ld"},{"en":"Iacocca rose from humble beginnings to become boss of Ford.","cn":"","src":"ld"}],"media":{"uk":"media/uk/humbly__gb_1.mp3","us":"media/us/humbly__us_1.mp3"},"oxford":{"phon":"ˈhʌmbli","pos":"adverb","senses":[{"en":"in a way that shows you do not think you are as important as other people","cn":"谦逊的；虚心的","ex":{"en":"I would humbly suggest that there is something wrong here.","cn":"愚以为此处有误。"}},{"en":"born into a low social position","cn":"（级别或地位）低下的，卑微的"}]}},"hurt":{"oxford":{"phon":"hɜːt","pos":"verb","senses":[{"en":"to cause physical pain to somebody/yourself; to injure somebody/yourself","cn":"（使）疼痛，受伤","g":"[transitive, intransitive]","lab":"especially British English","ex":{"en":"He hurt his back playing squash.","cn":"他打壁球时背部受伤了。"}},{"en":"to feel painful","cn":"感到疼痛","g":"[intransitive]","ex":{"en":"My feet hurt.","cn":"我脚疼。"}},{"en":"to make somebody unhappy or upset","cn":"使不快；使烦恼","g":"[intransitive, transitive]","ex":{"en":"What really hurt was that he never answered my letter.","cn":"真正让我伤心的是他从不给我回信。"}},{"en":"to feel unhappy or upset","cn":"感到不高兴（或烦恼）","g":"[intransitive]","lab":"informal","ex":{"en":"I know you're hurting and I want to help you.","cn":"我知道你心烦，我想帮助你。"}},{"en":"to have a bad effect on somebody/something","cn":"对…有不良影响","g":"[transitive]","ex":{"en":"Hard work never hurt anyone.","cn":"努力工作绝无害处。"}},{"en":"to be in a difficult situation because you need something, especially money","cn":"处于困境；手头拮据","g":"[intransitive]","lab":"North American English","ex":{"en":"His campaign is already hurting for money.","cn":"他从事的社会运动已经因缺乏经费而难以为继了。"}},{"en":"injured physically","cn":"（身体上）受伤的","ex":{"en":"None of the passengers were badly hurt.","cn":"乘客中没有人严重受伤。"},"pos":"adjective"},{"en":"upset and offended by something that somebody has said or done","cn":"（感情上）受伤的","ex":{"en":"a hurt look/expression","cn":"伤心的眼神／表情"},"pos":"adjective"},{"en":"a feeling of unhappiness because somebody has been unkind or unfair to you","cn":"心灵创伤；委屈","ex":{"en":"There was hurt and real anger in her voice.","cn":"她的声音里有难过，也有真正的愤怒。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使（自己或身体某部位）受伤","en":"If you hurt yourself or hurt a part of your body, you feel pain because you have injured yourself.","ex":{"en":"Yasin had seriously hurt himself while trying to escape from the police","cn":"亚辛试图从警察手中逃脱时受了重伤。"}},{"pos":"VERB 动词","cn":"（身体某部位）感到疼痛","en":"If a part of your body hurts, you feel pain there.","ex":{"en":"His collar bone only hurt when he lifted his arm.","cn":"他的锁骨只有在抬臂时才感觉到痛。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"受伤的","en":"If you are hurt, you have been injured.","ex":{"en":"His comrades asked him if he was hurt","cn":"战友问他是否受伤了。"}},{"pos":"VERB 动词","cn":"弄伤，弄痛（他人）","en":"If you hurt someone, you cause them to feel pain.","ex":{"en":"I didn't mean to hurt her, only to keep her still","cn":"我不是故意要弄痛她，只是想让她别乱动。"}},{"pos":"VERB 动词","cn":"伤害（感情）;使伤心","en":"If someone hurts you, they say or do something that makes you unhappy.","ex":{"en":"He is afraid of hurting Bessy's feelings","cn":"他怕伤害了贝茜的感情。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（感情上）受到伤害的，伤心的","en":"If you are hurt, you are upset because of something that someone has said or done.","ex":{"en":"Yes, I was hurt, jealous","cn":"是的，我感到伤心、嫉妒。"}},{"pos":"VERB 动词","cn":"伤心;感到痛苦","en":"If you say that you are hurting, you mean that you are experiencing emotional pain.","ex":{"en":"I am lonely and I am hurting.","cn":"我很孤单，很难过。"}},{"pos":"VERB 动词","cn":"危害;损害;妨碍;对…产生不良影响","en":"To hurt someone or something means to have a bad effect on them or prevent them from succeeding.","ex":{"en":"The combination of hot weather and decreased water supplies is hurting many industries","cn":"炎热的天气和供水的减少正危及很多行业。"}},{"pos":"N-VAR 可变名词","cn":"伤心;痛苦;委屈","en":"A feeling of hurt is a feeling that you have when you think that you have been treated badly or judged unfairly.","ex":{"en":"...feelings of hurt and anger, fear and despair","cn":"伤心、愤怒、恐惧、绝望的复杂情感"}},{"pos":"PHRASE 短语","cn":"（做…）不会有坏处","en":"If you say 'It won't hurt to do something' or 'It never hurts to do something', you are recommending an action which you think is helpful or useful.","ex":{"en":"It never hurts to ask","cn":"多问无妨。"}}]},"media":{"uk":"media/uk/hurt__gb_1.mp3","us":"media/us/hurt__us_1.mp3"},"examples":[{"en":"Our eyes were burning from the chemicals in the air.","cn":"空气中弥漫的化学物质熏得我们的眼睛火辣辣地痛。"},{"en":"His campaign is already hurting for money.","cn":"他从事的社会运动已经因缺乏经费而难以为继了。"}]},"hungry":{"media":{"uk":"media/uk/hungry__gb_1.mp3","us":"media/us/hungry__us_1.mp3"},"oxford":{"phon":"ˈhʌŋɡri","pos":"adjective","senses":[{"en":"feeling that you want to eat something","cn":"感到饿的","ex":{"en":"I'm really hungry.","cn":"我饿极了。"}},{"en":"not having enough food to eat","cn":"饥饿的；挨饿的","ex":{"en":"Thousands are going hungry because of the failure of this year's harvest.","cn":"由于今年粮食歉收，成千上万的人将挨饿。"}},{"en":"people who do not have enough food to eat","cn":"（统称）饥民","g":"[plural]"},{"en":"causing you to feel that you want to eat something","cn":"使人饥饿的；引起食欲的","g":"[only before noun]","ex":{"en":"All this gardening is hungry work.","cn":"这些园艺活儿让人干了肚子饿。"}},{"en":"having or showing a strong desire for something","cn":"渴望得到；渴求","ex":{"en":"power-hungry corporations","cn":"渴求权力的公司"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"饥饿的;感到饿的;辘辘饥肠的","en":"When you are hungry, you want some food because you have not eaten for some time and have an uncomfortable or painful feeling in your stomach.","ex":{"en":"My friend was hungry, so we drove to a shopping mall to get some food","cn":"我的朋友饿了，于是我们开车去一家购物中心吃饭。"}},{"pos":"PHRASE 短语","cn":"挨饿;吃不饱","en":"If people go hungry, they do not have enough food to eat.","ex":{"en":"Leonidas' family had been poor, he went hungry for years.","cn":"利奥尼达斯家曾经很穷，他有很多年都吃不饱肚子。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"渴望的;热望的","en":"If you say that someone is hungry for something, you are emphasizing that they want it very much.","ex":{"en":"Susan was certainly hungry for a life different from the one she had made for herself","cn":"苏珊无疑一心想过一种和现在不同的生活。"}}]},"examples":[{"en":"Thousands are going hungry because of the failure of this year's harvest.","cn":"由于今年粮食歉收，成千上万的人将挨饿。"},{"en":"They gazed hungrily at the display of food.","cn":"他们饥肠辘辘地盯着那些摆放着的食物。"}]},"hundreds":{"oxford":{"phon":"ˈhʌndrəd","pos":"number","senses":[{"en":"100","cn":"一百"},{"en":"You say a, one, two, several, etc. hundred without a final ‘s’ on ‘hundred’. Hundreds (of … ) can be used if there is no number or quantity before it. Always use a plural verb with hundred or hundreds , except when an amount of mo","cn":"说 a, one, two, several, etc. hundred 时，hundred 后面不加 s。若前面没有数目或数量，可用 hundreds (of ... )。除指金额外，hundred 和 hundreds 均用复数动词"}]}},"hunters":{"oxford":{"phon":"ˈhʌntə(r)","pos":"noun","senses":[{"en":"a person who hunts wild animals for food or sport; an animal that hunts its food","cn":"猎人；狩猎者；（猎食其他动物的）猎兽"},{"en":"( usually in compounds","cn":"通常构成复合词 ) a person who looks for and collects a particular kind of thing 搜集某种东西的人"}]}},"hurries":{"oxford":{"phon":"ˈhʌri","pos":"verb","senses":[{"en":"to do sth more quickly than usual because there is not much time","cn":"赶快，匆忙，急忙（做某事）"},{"en":"In spoken English hurry can be used with and plus another verb, instead of with to and the infinitive, especially to tell somebody to do something quickly.","cn":"英语口语中 hurry 可与 and 及所连接的另一个动词连用，而不和 to 所引导的不定式连用，尤用于告诉某人快点干某事"}]}},"huts":{"oxford":{"phon":"hʌt","pos":"noun","senses":[{"en":"a small, simply built house or shelter","cn":"简陋的小房子（或棚、舍）"}]}},"humans":{"oxford":{"phon":"ˈhjuːmən","pos":"adjective","senses":[{"en":"of or connected with people rather than animals, machines or gods","cn":"人的"},{"en":"showing the weaknesses that are typical of people, which means that other people should not criticize the person too much","cn":"显示人类特有弱点的；人本性的"}]}},"hurrying":{"oxford":{"phon":"ˈhʌri","pos":"verb","senses":[{"en":"to do sth more quickly than usual because there is not much time","cn":"赶快，匆忙，急忙（做某事）"},{"en":"In spoken English hurry can be used with and plus another verb, instead of with to and the infinitive, especially to tell somebody to do something quickly.","cn":"英语口语中 hurry 可与 and 及所连接的另一个动词连用，而不和 to 所引导的不定式连用，尤用于告诉某人快点干某事"}]}},"hummed":{"oxford":{"phon":"hʌm","pos":"verb","senses":[{"en":"to sing a tune with your lips closed","cn":"哼（曲子）"},{"en":"to make a low continuous sound","cn":"发嗡嗡声"}]}},"hunks":{"oxford":{"phon":"hʌŋk","pos":"noun","senses":[{"en":"a large piece of sth, especially food, that has been cut or broken from a larger piece （","cn":"尤指食物切下或掰下的）大块，大片"},{"en":"( informal ) a man who is big, strong and sexually attractive","cn":"魁梧性感的男子；猛男"}]}},"huff":{"collins":{"senses":[{"pos":"VERB 动词","cn":"生气;气恼;恼怒地说","en":"If you huff, you indicate that you are annoyed or offended about something, usually by the way that you say something.","ex":{"en":"'This', huffed Mr Buthelezi, 'was discrimination.'","cn":"“这个，”布特莱齐先生气愤地说，“是歧视。”"}},{"pos":"PHRASE 短语","cn":"生气;气恼;怒气冲冲","en":"If someone is in a huff, they are behaving in a bad-tempered way because they are annoyed and offended.","ex":{"en":"After the row in a pub he drove off in a huff.","cn":"在酒吧里吵了一架后，他气鼓鼓地开车走了。"}},{"pos":"PHRASE 短语","cn":"愤愤不满;生闷气","en":"If someone huffs and puffs, they express their annoyance or dissatisfaction with a decision or situation loudly but do not do anything to change it.","ex":{"en":"The British government huffed and puffed at the commission's decision.","cn":"英国政府对委员会的决定愤愤不满。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to breathe out in a noisy way, especially when you do something that involves a lot of physical effort","cn":"气喘吁吁"},{"en":"to show clearly that you strongly disagree with or are annoyed about something","cn":"强烈反对﹔发脾气"},{"en":"to say something in a way that shows you are annoyed, often because someone has offended you 〔","cn":"常指因受到冒犯而〕生气地说"}]},"collocations":{"phrases":["VERB + HUFF get in, go into | go off in, march off in, storm off in, walk off in She went off in a huff after losing the game.","PREP. in a ~ He's in a huff because he wasn't invited. | ~ at She got in a huff at being doubted. | ~ over Alison's in a huff over the joke "]},"media":{"uk":"media/ldoce/hwd/bre/d/huff_n0205.mp3","us":"media/ldoce/hwd/ame/5/huff1.mp3"},"examples":[{"en":"After much huffing and puffing, she finally agreed to help.","cn":"她生了好一阵闷气之后才终于同意帮忙。"},{"en":"‘Well, nobody asked you,’ she huffed irritably. “","cn":"哼，谁问你了。”她怒气冲冲地说。"}],"oxford":{"phon":"hʌf","pos":"verb","senses":[{"en":"to say something or make a noise in a way that shows you are offended or annoyed","cn":"生气地说；怒气冲冲","ex":{"en":"‘Well, nobody asked you,’ she huffed irritably.","cn":"“哼，谁问你了。”她怒气冲冲地说。"}}]}},"hurdle":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"障碍;困难;难关","en":"A hurdle is a problem, difficulty, or part of a process that may prevent you from achieving something.","ex":{"en":"Two-thirds of candidates fail at this first hurdle and are packed off home","cn":"三分之二的候选人在第一个难关就败下阵来，只好打包回家了。"}},{"pos":"N-COUNT-COLL 可数集合名词","cn":"跨栏赛跑;障碍赛跑","en":"Hurdles is a race in which people have to jump over a number of obstacles that are also called hurdles. You can use hurdles to refer to one or more races.","ex":{"en":"Davis won the 400m. hurdles in a new Olympic time of 49.3 sec.","cn":"戴维斯以49.3秒的成绩刷新奥运会纪录，在400米跨栏赛跑中一举夺冠。"}},{"pos":"VERB 动词","cn":"（在跑步过程中）跳跃，跨越","en":"If you hurdle, you jump over something while you are running.","ex":{"en":"He crossed the lawn and hurdled the short fence","cn":"他跑过草地，跳过低矮的栅栏。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something that happens which stops you making progress or which makes things worse than they were before","cn":""},{"en":"a problem or difficulty that must be dealt with before you can do or achieve something else","cn":""},{"en":"a fact or situation that will make it very difficult for something to be achieved","cn":""}]},"collocations":{"phrases":["VERB + HURDLE clear, jump (over) She cleared the first few hurdles easily. | fall at, hit His horse fell at the final hurdle. 2 problem/diff","ADJ. big, difficult | main, major | final, first, last, next The first big hurdle in putting your car on the road is getting insurance.","VERB + HURDLE face This is perhaps the most difficult hurdle that we face. | clear, jump, overcome, pass We'll jump each hurdle as we come t"]},"media":{"uk":"media/ldoce/hwd/bre/5/hurdle_n0205.mp3","us":"media/ldoce/hwd/ame/2/hurdle1.mp3"},"examples":[{"en":"His horse fell at the final hurdle.","cn":"他骑的马在最后一个跨栏倒下了。"},{"en":"The next hurdle will be getting her parents' agreement.","cn":"下一个难关是征得她父母的同意。"}],"oxford":{"phon":"ˈhɜːdl","pos":"noun","senses":[{"en":"each of a series of vertical frames that a person or horse jumps over in a race","cn":"（供人或马在赛跑中跨越的）栏架，跨栏","ex":{"en":"His horse fell at the final hurdle.","cn":"他骑的马在最后一个栏架倒下了。"}},{"en":"a race in which runners or horses have to jump over hurdles","cn":"跨栏赛","g":"[plural]","ex":{"en":"the 300 m hurdles","cn":"300 米跨栏赛"}},{"en":"a problem or difficulty that must be solved or dealt with before you can achieve something","cn":"难关；障碍","ex":{"en":"The next hurdle will be getting her parents' agreement.","cn":"下一个难关是征得她父母的同意。"}},{"en":"to jump over something while you are running","cn":"（奔跑中）跳越（某物）","g":"[transitive, intransitive]","ex":{"en":"He hurdled two barriers to avoid reporters.","cn":"他跳过了两个障碍物以躲避记者。"},"pos":"verb"},{"en":"to run in a hurdles race","cn":"参加跨栏赛","g":"[intransitive]","pos":"verb"}]}},"hurricane":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"飓风","en":"A hurricane is an extremely violent wind or storm."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a period of very bad weather when there is a lot of rain or snow, strong winds, and often lightning","cn":""},{"en":"a storm in which there is a lot of thunder (= loud noise in the sky ) and lightning (= flashes of light in the sky )","cn":""},{"en":"a storm that has very strong fast winds and that moves over water – used about storms in the North Atlantic Ocean","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A hurricane is a severe tropical storm with high winds and heavy rain. When a hurricane comes through your town, you should board up the windows and stay inside."}]},"collocations":{"phrases":["HURRICANE + VERB hit sth, strike (sth) A hurricane hit the city yesterday at 5 p.m. | damage sth, destroy sth, devastate sth The fields were","HURRICANE + NOUN force hurricane-force winds","PREP. in a/the ~ The roof blew off in a hurricane.","PHRASES the eye of the hurricane (= the central point)"]},"media":{"uk":"media/ldoce/hwd/bre/f/hurricane0205.mp3","us":"media/ldoce/hwd/ame/2/hurricane1.mp3"},"examples":[{"en":"Hurricane Betty is now approaching the coast of Florida.","cn":"飓风贝蒂正在逼近佛罗里达州海岸。"},{"en":"hurricane-force winds","cn":"飓风级大风"}],"oxford":{"phon":"ˈhʌrɪkən","pos":"noun","senses":[{"en":"a violent storm with very strong winds, especially in the western Atlantic Ocean","cn":"（尤指西大西洋的）飓风","lab":"North American English","ex":{"en":"A powerful hurricane hit the Florida coast.","cn":"强飓风袭击了佛罗里达海岸。"}}]}},"hurtful":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"伤人感情的;使人痛苦的;刻薄的","en":"If you say that someone's comments or actions are hurtful, you mean that they are unkind and upsetting.","ex":{"en":"Her comments can only be hurtful to Mrs Green's family.","cn":"她的话只会使格林夫人的家人感到伤心。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"treating people in a way that makes them unhappy or upset. Unkind sounds rather formal. In everyday English, people usually say mean or nasty","cn":""},{"en":"unkind","cn":""},{"en":"deliberately unkind, and seeming to enjoy making people unhappy","cn":""}]},"collocations":{"phrases":["VERBS be | find sth I found some of his comments rather hurtful.","ADV. deeply, very She made some very hurtful remarks. | a bit, rather","PREP. to What he said was deeply hurtful to me."]},"media":{"uk":"media/ldoce/hwd/bre/1/hurtful0205.mp3","us":"media/ldoce/hwd/ame/5/hurtful.mp3"},"examples":[{"en":"He said, rather hurtfully, that he had better things to do than come and see me.","cn":"他相当刻薄地说来看我还不如去干别的事。"},{"en":"The bad reviews of her new book were very hurtful to her.","cn":"对她的新书的负面评论使她很难过。"}],"oxford":{"phon":"ˈhɜːtfl","pos":"adjective","senses":[{"en":"making you feel upset and offended","cn":"伤感情的；伤害自尊的","ex":{"en":"I cannot forget the hurtful things he said.","cn":"我无法忘记他说的那些伤感情的话。"}}]}},"hunch":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"直觉;预感;第六感","en":"If you have a hunch about something, you are sure that it is correct or true, even though you do not have any proof.","ex":{"en":"I had a hunch that Susan and I would work well together","cn":"我有预感和苏珊共事会很融洽。"}},{"pos":"VERB 动词","cn":"（常指因寒冷、生病或愁苦而）耸肩弓身，蜷起身子","en":"If you hunch forward, you raise your shoulders, put your head down, and lean forwards, often because you are cold, ill, or unhappy.","ex":{"en":"He got out his map of Yorkshire and hunched over it to read the small print.","cn":"他拿出约克郡地图，弓身趴在上面努力看清那些细小的字体。"}},{"pos":"VERB 动词","cn":"耸起（双肩）","en":"If you hunch your shoulders, you raise them and lean forwards slightly.","ex":{"en":"Wes hunched his shoulders and leaned forward on the edge of the counter.","cn":"韦斯耸起双肩，身体前倾靠在柜台边上。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the answer you give when you are trying to guess a number or amount but are not able to be exact","cn":""},{"en":"a strange feeling that you know the answer to something, even though you have very little information to help you to guess","cn":""},{"en":"a guess, especially an answer, that seems stupid or is very likely to be wrong","cn":""}]},"vocab":{"pos":"1 n 2 v n","senses":[{"en":"When you pose for pictures with short friends, you hunch over so you don't tower above them — you scrunch up your shoulders, bend your knees, and try to look smaller."}]},"collocations":{"phrases":["VERB + HUNCH have I had a hunch that she was not telling the truth. | act on, follow, play Acting on a hunch, I waited outside her house to ","PREP. on a ~ I phoned on a hunch to ask if they had any work for me."]},"media":{"uk":"media/ldoce/hwd/bre/2/hunch_v0205.mp3","us":"media/ldoce/hwd/ame/5/hunch1.mp3"},"examples":[{"en":"He hunched his shoulders and thrust his hands deep into his pockets.","cn":"他耸着肩，双手深深地插进衣袋。"},{"en":"She leaned forward, hunching over the desk.","cn":"她身体前倾，伏在写字台上。"}],"oxford":{"phon":"hʌntʃ","pos":"verb","senses":[{"en":"to bend the top part of your body forward and raise your shoulders and back","cn":"弓身；弓背；耸肩","ex":{"en":"She leaned forward, hunching over the desk.","cn":"她身体前倾，伏在写字台上。"}},{"en":"a feeling that something is true even though you do not have any evidence to prove it","cn":"预感；直觉","ex":{"en":"It seemed that the doctor's hunch had been right.","cn":"看起来医生的直觉是对的。"},"pos":"noun"}]}},"hum":{"collins":{"senses":[{"pos":"VERB 动词","cn":"发出连续而低沉的声音;发嗡嗡声","en":"If something hums, it makes a low continuous noise.","ex":{"en":"The birds sang, the bees hummed","cn":"鸟儿叫，蜂儿鸣。"}},{"pos":"VERB 动词","cn":"哼（曲子）","en":"When you hum a tune, you sing it with your lips closed.","ex":{"en":"She was humming a merry little tune","cn":"她哼着一支欢快的小曲儿。"}},{"pos":"VERB 动词","cn":"(地方）热闹，活跃，繁忙","en":"If you say that a place hums, you mean that it is full of activity.","ex":{"en":"The place is really beginning to hum","cn":"这个地方真正开始热闹起来了。"}},{"pos":"CONVENTION 惯用语","cn":"（踌躇时发出的声音）嗯，呃","en":"Hum is sometimes used to represent the sound people make when they are not sure what to say.","ex":{"en":"Hum, I am sorry but I thought you were French.","cn":"嗯，很抱歉，我以为你是法国人。"}},{"pos":"See also:","cn":"","en":"hum and haw→see: ;"}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make musical sounds with your voice, but with your mouth closed","cn":""},{"en":"to make musical sounds by blowing air out between your lips","cn":""},{"en":"to make a continuous sound, for example, like the sound made by bees","cn":""}]},"collocations":{"phrases":["ADV. quietly, softly | happily | tunelessly | along humming along with the music","VERB + HUM begin to He began to hum, somewhat tunelessly.","PHRASES hum to yourself She was humming softly to herself."]},"media":{"uk":"media/ldoce/hwd/bre/d/hum_v0205.mp3","us":"media/ldoce/hwd/ame/4/hum.mp3"},"examples":[{"en":"The room filled with the hum of conversation.","cn":"房间里充满了嘈杂的谈话声。"},{"en":"She was humming softly to herself.","cn":"她在轻声哼着曲子。"}],"oxford":{"phon":"hʌm","pos":"verb","senses":[{"en":"to sing a tune with your lips closed","cn":"哼（曲子）","g":"[intransitive, transitive]","lab":"British English","ex":{"en":"She was humming softly to herself.","cn":"她在轻声哼着曲子。"}},{"en":"to make a low continuous sound","cn":"发嗡嗡声","g":"[intransitive]","ex":{"en":"The computers were humming away.","cn":"计算机在嗡嗡作响。"}},{"en":"to be full of activity","cn":"活跃；繁忙","g":"[intransitive]","ex":{"en":"The streets were beginning to hum with life.","cn":"街道开始热闹起来。"}},{"en":"a low continuous sound","cn":"嗡嗡声；嘈杂声","ex":{"en":"the hum of bees/traffic/voices","cn":"蜜蜂的嗡嗡声；车辆的呜呜声；人的嘈杂声"},"pos":"noun"}]}},"humiliation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"耻辱;屈辱;丢脸;蒙羞","en":"Humiliation is the embarrassment and shame you feel when someone makes you appear stupid, or when you make a mistake in public.","ex":{"en":"She faced the humiliation of discussing her husband's affair.","cn":"她面临要谈及丈夫外遇的羞辱。"}},{"pos":"N-COUNT 可数名词","cn":"丢脸的事;尴尬的场合","en":"A humiliation is an occasion or a situation in which you feel embarrassed and ashamed.","ex":{"en":"The result is a humiliation for the prime minister.","cn":"这一结果让首相出丑。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the feeling you have when you feel guilty and embarrassed because you, or someone who is close to you, have done something wrong","cn":""},{"en":"a feeling of shame and embarrassment because you have been made to look weak or stupid in front of other people","cn":""},{"en":"the loss of other people’s respect because you have done something bad, or you have been unsuccessful","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Humiliation describes a strong feeling of embarrassment or mortification — like that time in sixth grade when your mother wiped your face and called you \"honey bunny\" in front of all your friends."}]},"collocations":{"phrases":["ADJ. great, intense, painful | total | further | public | national | final, ultimate He was forced to face the ultimate humiliation the next","VERB + HUMILIATION be subjected to, endure, face, suffer She suffered the humiliation of having her house searched. | feel feeling the inten","PHRASES a feeling/sense of humiliation"]},"media":{"uk":"media/ldoce/hwd/bre/a/humiliation0205.mp3","us":"media/ldoce/hwd/ame/d/laadhumiliation.mp3"},"examples":[{"en":"She suffered the humiliation of being criticized in public.","cn":"她当众受到指责，丢了面子。"},{"en":"the humiliation of having to ask her parents for money","cn":"不得不开口向她父母要钱的难堪"}],"oxford":{"phon":"hjuːˌmɪliˈeɪʃn","pos":"noun","senses":[{"en":"a feeling of being ashamed or stupid and having lost the respect of other people; the act of making somebody feel like this","cn":"丢脸，蒙羞；羞辱","ex":{"en":"She suffered the humiliation of being criticized in public.","cn":"她当众受到指责，丢了面子。"}}]}},"humidity":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"潮湿","en":"You say there is humidity when the air feels very heavy and damp.","ex":{"en":"The heat and humidity were insufferable.","cn":"高温和潮湿让人难以忍受。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（空气）湿度","en":"Humidity is the amount of water in the air.","ex":{"en":"The humidity is relatively low.","cn":"湿度相对较低。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the amount of water contained in the air","cn":"湿度﹔湿气"},{"en":"when the air is very warm and wet","cn":"湿热"}]},"vocab":{"pos":"n","senses":[{"en":"Humidity has to do with how much moisture is in the air. High humidity is a lot of moisture; low humidity is not much at all."}]},"collocations":{"phrases":["ADJ. high, low | ambient, relative in dry weather, when the ambient humidity is low","QUANT. level","HUMIDITY + VERB increase, rise | decrease, fall","HUMIDITY + NOUN level | control The museum is equipped with sophisticated humidity controls."]},"media":{"uk":"media/ldoce/hwd/bre/5/humidity0205.mp3","us":"media/ldoce/hwd/ame/8/humidity.mp3"},"examples":[{"en":"These plants need heat and humidity to grow well.","cn":"这些植物在高温潮湿的环境中才能生长得旺盛。"},{"en":"The humidity was becoming unbearable.","cn":"这种潮湿使人越来越难以忍受了。"}],"oxford":{"phon":"hjuːˈmɪdəti","pos":"noun","senses":[{"en":"the amount of water in the air","cn":"（空气中的）湿度","ex":{"en":"Instruments constantly monitor temperature and humidity.","cn":"仪器始终在监测温度和湿度。"}},{"en":"conditions in which the air is wet and very warm","cn":"湿热；高温潮湿","ex":{"en":"These plants need heat and humidity to grow well.","cn":"这些植物在高温潮湿的环境中才能生长得旺盛。"}}]}},"humiliate":{"collins":{"senses":[{"pos":"VERB 动词","cn":"羞辱;使蒙羞;使出丑","en":"To humiliate someone means to say or do something which makes them feel ashamed or stupid.","ex":{"en":"She had been beaten and humiliated by her husband","cn":"她遭到丈夫的殴打和羞辱。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone feel ashamed","cn":""},{"en":"to make someone feel very ashamed and upset, especially by making them look weak or stupid","cn":""},{"en":"if you disgrace yourself or disgrace your family, your school etc, you behave very badly so that other people lose respect for you or for your family or school","cn":""}]},"vocab":{"pos":"v","senses":[{"en":"Humiliate means to make someone feel ashamed or stupid, often publicly. It would humiliate all but the most self-assured person to realize that everyone else in the room has noticed their fly is down."}]},"collocations":{"phrases":["ADV. deeply | totally, utterly | publicly Lowe was publicly humiliated by his colleagues.","PREP. in front of I had been assaulted and deeply humiliated in front of all my friends.","PHRASES feel humiliated I have never felt so humiliated in all my life."]},"media":{"uk":"media/ldoce/hwd/bre/a/humiliate0205.mp3","us":"media/ldoce/hwd/ame/9/humiliate.mp3"},"examples":[{"en":"I didn't want to humiliate her in front of her colleagues.","cn":"我不想当着她同事们的面令她难堪。"},{"en":"The party was humiliated in the recent elections.","cn":"该党在新近的选举中耻辱地失败了。"}],"oxford":{"phon":"hjuːˈmɪlieɪt","pos":"verb","senses":[{"en":"to make somebody feel ashamed or stupid and lose the respect of other people","cn":"羞辱；使丧失尊严","ex":{"en":"I didn't want to humiliate her in front of her colleagues.","cn":"我不想当着她同事们的面令她难堪。"}}]}}});
